function validate([s, t]) {
  if (typeof s !== 'string' || typeof t !== 'string') return 's and t must be strings.';
  if (s.length < 1 || s.length > 200 || t.length < 1 || t.length > 200) return 's and t each have 1 to 200 characters.';
  if (!/^[a-z#]*$/.test(s) || !/^[a-z#]*$/.test(t)) return "Only lowercase letters and '#' are allowed.";
  return null;
}

