function generate(rand, size) {
  const large = size === 'large';
  const limit = large ? 200 : 8;
  const letter = () => 'abc'[Math.floor(rand() * (large ? 3 : 2))];
  const keys = (length) => Array.from({ length }, () => (rand() < 0.35 ? '#' : letter())).join('');
  const length = () => (large ? 150 + Math.floor(rand() * 51) : 1 + Math.floor(rand() * limit));
  const typeOut = (str) => {
    const out = [];
    for (const ch of str) {
      if (ch === '#') out.pop();
      else out.push(ch);
    }
    return out;
  };
  const s = keys(length());
  const mode = rand();
  if (mode < 0.35) return [s, keys(length())];
  // Type the same final text as s (or a near miss of it) with extra keystrokes that get erased.
  const text = typeOut(s);
  if (mode < 0.65 && text.length > 0) {
    const at = Math.floor(rand() * text.length);
    if (rand() < 0.5) text[at] = text[at] === 'a' ? 'b' : 'a';
    else text.splice(at, 1);
  }
  let t = rand() < 0.3 ? '#' : '';
  for (const ch of text) {
    if (rand() < 0.3) t += letter() + '#';
    if (rand() < 0.1) t += letter() + letter() + '##';
    t += ch;
  }
  if (rand() < 0.3) t += letter() + '#';
  if (t.length > limit) t = text.join('');
  if (t.length === 0) t = '#';
  return rand() < 0.5 ? [s, t] : [t, s];
}
